// Parse input data - v2 avec support preprocessing + section
const input = $input.first().json;
const body = input.body || input;

const CHUNK_THRESHOLD = 10000; // 10K chars

const languageNames = {
  'fr': 'français',
  'en': 'English',
  'es': 'español',
  'he': 'hébreu',
  'ar': 'araméen',
  'de': 'allemand',
  'it': 'italien'
};

const sourceLanguage = body.source_language || 'he';
const targetLanguage = body.target_language || 'fr';
const needsPivot = sourceLanguage !== 'en' && targetLanguage !== 'en';

// Support section || page for complex sources
const section = body.section || body.page || null;
const page = body.page || body.section || null;

// Handle segments
let segments = [];
if (Array.isArray(body.segments)) {
  segments = body.segments;
} else if (body.text) {
  segments = [body.text];
}

// Analyze each segment for preprocessing needs
const analyzedSegments = segments.map((segment, idx) => {
  const isObject = typeof segment === 'object' && segment !== null;
  const segmentText = isObject ? segment.text : segment;
  const charCount = segmentText.length;

  // Detect images
  const imageRegex = /<img[^>]+src=["']([^"']+)["'][^>]*>/gi;
  const imageMatches = [...segmentText.matchAll(imageRegex)];
  const imageUrls = imageMatches.map(m => m[1]);

  return {
    index: idx,
    text: segmentText,
    commentary_id: isObject ? segment.commentary_id : null,
    source_text_id: isObject ? segment.source_text_id : null,
    char_count: charCount,
    needs_chunking: charCount > CHUNK_THRESHOLD,
    has_images: imageUrls.length > 0,
    image_urls: imageUrls
  };
});

const metadata = {
  ...(body.metadata || {}),
  commentator: body.commentator || body.metadata?.commentator
};

return [{
  json: {
    jobId: body.job_id,
    traite: body.traite,
    section: section,
    page: page,
    locationLabel: section || page || '',
    jobType: body.job_type || 'unit_translation',
    mode: body.mode || 'standard',
    sourceLanguage: sourceLanguage,
    sourceLangName: languageNames[sourceLanguage] || sourceLanguage,
    targetLanguage: targetLanguage,
    targetLangName: languageNames[targetLanguage] || targetLanguage,
    needsPivot: needsPivot,
    llmProvider: body.llm_provider || 'anthropic',
    modelAnthropic: body.model_anthropic || 'claude-sonnet-4-20250514',
    apiKey: body.api_key,
    openaiApiKey: body.openai_api_key,
    mistralApiKey: body.mistral_api_key,
    segments: analyzedSegments,
    segmentsCount: segments.length,
    needsPreprocessing: analyzedSegments.some(s => s.needs_chunking || s.has_images),
    context: body.context || {},
    metadata: metadata,
    requestId: body.request_id,
    startTime: Date.now(),
    chunkThreshold: CHUNK_THRESHOLD
  }
}];

// Split analyzed segments into items for processing
const input = $('Parse Input').first().json;

const items = input.segments.map((segment) => {
  return {
    json: {
      ...segment,
      totalSegments: input.segments.length,
      jobId: input.jobId,
      traite: input.traite,
      section: input.section,
      page: input.page,
      locationLabel: input.locationLabel,
      jobType: input.jobType,
      mode: input.mode,
      sourceLanguage: input.sourceLanguage,
      sourceLangName: input.sourceLangName,
      targetLanguage: input.targetLanguage,
      targetLangName: input.targetLangName,
      needsPivot: input.needsPivot,
      llmProvider: input.llmProvider,
      modelAnthropic: input.modelAnthropic,
      apiKey: input.apiKey,
      openaiApiKey: input.openaiApiKey,
      mistralApiKey: input.mistralApiKey,
      context: input.context,
      metadata: input.metadata,
      requestId: input.requestId,
      startTime: input.startTime,
      chunkThreshold: input.chunkThreshold
    }
  };
});

return items;

// Parse Claude's chunking response
const input = $input.first().json;
const originalData = $('Needs Chunking?').first().json;

try {
  const body = input.body || input;
  const content = body.content?.[0]?.text || '';

  // Try to parse JSON from response
  let jsonStr = content;
  const jsonMatch = content.match(/```json\n?([\s\S]*?)\n?```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1];
  }

  const parsed = JSON.parse(jsonStr);
  const chunks = parsed.chunks || [];

  if (chunks.length === 0) {
    // Fallback: return original as single chunk
    return [{
      json: {
        ...originalData,
        chunks: [{ index: 0, text: originalData.text, char_count: originalData.char_count }],
        total_chunks: 1,
        split_method: 'fallback_single'
      }
    }];
  }

  return [{
    json: {
      ...originalData,
      chunks: chunks,
      total_chunks: chunks.length,
      split_method: 'claude_semantic'
    }
  }];
} catch (e) {
  // Error parsing: return original as single chunk
  return [{
    json: {
      ...originalData,
      chunks: [{ index: 0, text: originalData.text, char_count: originalData.char_count }],
      total_chunks: 1,
      split_method: 'fallback_error',
      split_error: e.message
    }
  }];
}

// No chunking needed - wrap text as single chunk
const input = $input.first().json;

return [{
  json: {
    ...input,
    chunks: [{ index: 0, text: input.text, char_count: input.char_count }],
    total_chunks: 1,
    split_method: 'none'
  }
}];

// Extract image URLs and prepare OCR calls
const input = $input.first().json;
const imageUrls = input.image_urls || [];

if (imageUrls.length === 0 || !input.mistralApiKey) {
  // No images or no API key - continue without OCR
  return [{
    json: {
      ...input,
      ocr_texts: [],
      ocr_status: 'skipped'
    }
  }];
}

// For now, mark for OCR processing
// In a full implementation, we'd call image-ocr webhook here
return [{
  json: {
    ...input,
    ocr_texts: [],
    ocr_status: 'pending',
    ocr_note: 'OCR processing would be called here for: ' + imageUrls.join(', ')
  }
}];

// No images to process
const input = $input.first().json;

return [{
  json: {
    ...input,
    ocr_texts: [],
    ocr_status: 'none'
  }
}];

// Expand chunks into individual items for translation
const input = $input.first().json;
const chunks = input.chunks || [{ index: 0, text: input.text }];

const items = chunks.map((chunk, idx) => {
  return {
    json: {
      chunkIndex: idx,
      chunkText: chunk.text,
      chunkCharCount: chunk.char_count || chunk.text.length,
      originalSegmentIndex: input.index,
      totalChunks: chunks.length,
      totalSegments: input.totalSegments,
      jobId: input.jobId,
      traite: input.traite,
      section: input.section,
      page: input.page,
      locationLabel: input.locationLabel,
      jobType: input.jobType,
      mode: input.mode,
      sourceLanguage: input.sourceLanguage,
      sourceLangName: input.sourceLangName,
      targetLanguage: input.targetLanguage,
      targetLangName: input.targetLangName,
      needsPivot: input.needsPivot,
      llmProvider: input.llmProvider,
      modelAnthropic: input.modelAnthropic,
      apiKey: input.apiKey,
      openaiApiKey: input.openaiApiKey,
      context: input.context,
      metadata: input.metadata,
      commentary_id: input.commentary_id,
      source_text_id: input.source_text_id,
      split_method: input.split_method,
      ocr_texts: input.ocr_texts || []
    }
  };
});

return items;

// Extract English translation from pivot step 1
const input = $input.first().json;
const prevData = $('Needs Pivot?').first().json;

try {
  const body = input.body || input;
  const content = body.content?.[0]?.text || '';
  const usage = body.usage || {};

  return [{
    json: {
      ...prevData,
      intermediateTranslation: content,
      pivotTokens: {
        input_tokens: usage.input_tokens || 0,
        output_tokens: usage.output_tokens || 0
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      ...prevData,
      intermediateTranslation: '',
      pivotError: e.message
    }
  }];
}

// Extract final translation from pivot step 2
const input = $input.first().json;
const prevData = $('Extract Step 1').first().json;

try {
  const body = input.body || input;
  const content = body.content?.[0]?.text || '';
  const usage = body.usage || {};

  return [{
    json: {
      ...prevData,
      finalTranslation: content,
      claudeTokens: {
        input_tokens: (prevData.pivotTokens?.input_tokens || 0) + (usage.input_tokens || 0),
        output_tokens: (prevData.pivotTokens?.output_tokens || 0) + (usage.output_tokens || 0)
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      ...prevData,
      finalTranslation: prevData.intermediateTranslation || '',
      translateError: e.message
    }
  }];
}

// Extract direct translation
const input = $input.first().json;
const prevData = $('Needs Pivot?').first().json;

try {
  const body = input.body || input;
  const content = body.content?.[0]?.text || '';
  const usage = body.usage || {};

  return [{
    json: {
      ...prevData,
      finalTranslation: content,
      claudeTokens: {
        input_tokens: usage.input_tokens || 0,
        output_tokens: usage.output_tokens || 0
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      ...prevData,
      finalTranslation: '',
      translateError: e.message
    }
  }];
}

// Accumulate chunk translation for recombination
const input = $input.first().json;

return [{
  json: {
    chunkIndex: input.chunkIndex,
    originalSegmentIndex: input.originalSegmentIndex,
    originalText: input.chunkText,
    translation: input.finalTranslation,
    totalChunks: input.totalChunks,
    claudeTokens: input.claudeTokens || { input_tokens: 0, output_tokens: 0 },
    commentary_id: input.commentary_id,
    metadata: input.metadata,
    jobId: input.jobId,
    traite: input.traite,
    section: input.section,
    page: input.page,
    targetLanguage: input.targetLanguage
  }
}];

// Recombine chunks when segment is complete
// This runs after all chunks of a segment are processed
const allItems = $input.all();

// Group by originalSegmentIndex
const grouped = {};
for (const item of allItems) {
  const segIdx = item.json.originalSegmentIndex;
  if (!grouped[segIdx]) {
    grouped[segIdx] = [];
  }
  grouped[segIdx].push(item.json);
}

// Sort and recombine
const results = [];
for (const segIdx of Object.keys(grouped).sort((a, b) => parseInt(a) - parseInt(b))) {
  const chunks = grouped[segIdx].sort((a, b) => a.chunkIndex - b.chunkIndex);
  const combinedTranslation = chunks.map(c => c.translation).join('\n\n');
  const combinedOriginal = chunks.map(c => c.originalText).join('\n\n');
  const totalTokens = chunks.reduce((acc, c) => ({
    input_tokens: acc.input_tokens + (c.claudeTokens?.input_tokens || 0),
    output_tokens: acc.output_tokens + (c.claudeTokens?.output_tokens || 0)
  }), { input_tokens: 0, output_tokens: 0 });

  results.push({
    json: {
      segmentIndex: parseInt(segIdx),
      originalText: combinedOriginal,
      translation: combinedTranslation,
      chunks_count: chunks.length,
      claudeTokens: totalTokens,
      commentary_id: chunks[0].commentary_id,
      metadata: chunks[0].metadata,
      jobId: chunks[0].jobId,
      traite: chunks[0].traite,
      section: chunks[0].section,
      page: chunks[0].page,
      targetLanguage: chunks[0].targetLanguage
    }
  });
}

return results;
